const items = $input.all();

// ========================================
// CURRENT DATE - INDIA TIME
// ========================================

const indiaDateString = new Intl.DateTimeFormat("en-CA", {
  timeZone: "Asia/Kolkata",
  year: "numeric",
  month: "2-digit",
  day: "2-digit",
}).format(new Date());

const [todayYear, todayMonth, todayDay] = indiaDateString
  .split("-")
  .map(Number);

const today = new Date(
  todayYear,
  todayMonth - 1,
  todayDay
);

today.setHours(0, 0, 0, 0);


// ========================================
// DATE COLUMNS
// ========================================

const DATE_COLUMNS = [
  "ETD TUT",
  "ETA",
  "ETD",
  "ETA_1",
  "ETD_1",
  "ETA_2"
];


// ========================================
// HELPER FUNCTIONS
// ========================================

function isEmpty(value) {

  return (
    value === undefined ||
    value === null ||
    value.toString().trim() === ""
  );
}


function normalizeStatus(value) {

  return (value ?? "")
    .toString()
    .trim()
    .toUpperCase();
}


function parseDate(value) {

  if (isEmpty(value)) {
    return null;
  }


  // =====================================
  // EXCEL SERIAL DATE
  // =====================================

  if (typeof value === "number") {

    const excelEpoch = new Date(
      Date.UTC(1899, 11, 30)
    );

    const date = new Date(
      excelEpoch.getTime() +
      value * 86400000
    );

    return new Date(
      date.getUTCFullYear(),
      date.getUTCMonth(),
      date.getUTCDate()
    );
  }


  // =====================================
  // TEXT DATE
  // =====================================

  const str = value
    .toString()
    .trim();

  let parts = null;


  if (str.includes(".")) {

    parts = str.split(".");

  } else if (str.includes("/")) {

    parts = str.split("/");

  } else if (str.includes("-")) {

    parts = str.split("-");

  }


  if (
    !parts ||
    parts.length !== 3
  ) {

    return null;
  }


  let day = Number(parts[0]);

  let month = Number(parts[1]);

  let year = Number(parts[2]);


  if (
    Number.isNaN(day) ||
    Number.isNaN(month) ||
    Number.isNaN(year)
  ) {

    return null;
  }


  if (year < 100) {

    year += 2000;

  }


  const date = new Date(
    year,
    month - 1,
    day
  );


  date.setHours(
    0,
    0,
    0,
    0
  );


  if (
    date.getFullYear() !== year ||
    date.getMonth() !== month - 1 ||
    date.getDate() !== day
  ) {

    return null;

  }


  return date;
}


function sameDate(date1, date2) {

  if (
    !date1 ||
    !date2
  ) {

    return false;

  }


  return (
    date1.getTime() ===
    date2.getTime()
  );
}


function sevenDaysBefore(date) {

  const result = new Date(date);

  result.setDate(
    result.getDate() - 7
  );

  result.setHours(
    0,
    0,
    0,
    0
  );

  return result;
}


function formatDate(date) {

  if (!date) {

    return "";

  }


  return [

    String(
      date.getDate()
    ).padStart(2, "0"),

    String(
      date.getMonth() + 1
    ).padStart(2, "0"),

    date.getFullYear()

  ].join("-");
}


// ========================================
// FIND RELEVANT SHIPMENT DATE
// ========================================

function getRelevantShipmentDate(row) {

  for (const column of DATE_COLUMNS) {

    const date = parseDate(
      row[column]
    );

    if (date) {

      return formatDate(date);

    }
  }


  return "";
}


// ========================================
// CREATE EMAIL TABLE ROW
// ========================================

function createReminderRow(
  row,
  reminderDate,
  reason
) {

  return {

    DATE: reminderDate,

    SHIPPER:
      row["SHIPPER NAME"] ?? "",

    CARRIER:
      row["CARRIER"] ?? "",

    "B.NO":
      row["B.NO"] ?? "",

    "JOB NO":
      row["JOB NO / HBL NO"] ??
      row["JOB NO"] ??
      "",

    "MBL NO":
      row["MBL NO"] ?? "",

    "CTNR NO":
      row["CTNR NO"] ?? "",

    REASON:
      reason

  };
}


// ========================================
// FIVE EMAIL CATEGORIES
// ========================================

const categories = {


  HBL: {

    category: "HBL",

    title:
      "HBL Status Reminder",

    subject:
      "HBL Status Reminder",

    rows: []

  },


  MBL: {

    category: "MBL",

    title:
      "MBL Status Reminder",

    subject:
      "MBL Status Reminder",

    rows: []

  },


  DATE: {

    category: "DATE",

    title:
      "Shipment Date Reminder",

    subject:
      "Shipment Date Reminder",

    rows: []

  },


  PREALERT: {

    category: "PREALERT",

    title:
      "Pre-Alert Reminder",

    subject:
      "Pre-Alert Reminder",

    rows: []

  },


  REVENUE: {

    category: "REVENUE",

    title:
      "Revenue Reminder",

    subject:
      "Revenue Reminder",

    rows: []

  }

};


// ========================================
// CHECK EVERY EXCEL ROW
// ========================================

for (const item of items) {


  const row = item.json;


  // =====================================
  // IGNORE BLANK ROWS
  // =====================================

  const hasShipmentData =

    !isEmpty(
      row["SHIPPER NAME"]
    ) ||

    !isEmpty(
      row["B.NO"]
    ) ||

    !isEmpty(
      row["JOB NO / HBL NO"]
    ) ||

    !isEmpty(
      row["MBL NO"]
    ) ||

    !isEmpty(
      row["CTNR NO"]
    );


  if (!hasShipmentData) {

    continue;

  }


  // =====================================
  // 1. HBL STATUS
  // =====================================

  const hblStatus =
    normalizeStatus(
      row["HBL STATUS"]
    );


  if (
    hblStatus !== "RECEIVED"
  ) {


    categories.HBL.rows.push(

      createReminderRow(

        row,

        getRelevantShipmentDate(row),

        "HBL STATUS NOT RELEASED"

      )

    );

  }


  // =====================================
  // 2. MBL STATUS
  // =====================================

  const mblStatus =
    normalizeStatus(
      row["MBL STATUS"]
    );


  if (
    mblStatus !== "RECEIVED"
  ) {


    categories.MBL.rows.push(

      createReminderRow(

        row,

        getRelevantShipmentDate(row),

        "MBL STATUS NOT RELEASED"

      )

    );

  }


  // =====================================
  // 3. TODAY'S SHIPMENT DATE
  // =====================================

  const matchedDateReasons = [];


  for (
    const column of DATE_COLUMNS
  ) {


    const shipmentDate =
      parseDate(
        row[column]
      );


    if (
      shipmentDate &&
      sameDate(
        shipmentDate,
        today
      )
    ) {


    matchedDateReasons.push(
      "TODAY VESSEL SELLING"
    );

    }

  }


  if (
    matchedDateReasons.length > 0
  ) {


    categories.DATE.rows.push(

      createReminderRow(

        row,

        formatDate(today),

        matchedDateReasons.join(" | ")

      )

    );

  }


  // =====================================
  // 4. PRE-ALERT
  // =====================================

  const preAlert =
    row["PRE-ALERT"];


  const etdTut =
    parseDate(
      row["ETD TUT"]
    );


  if (
    isEmpty(preAlert) &&
    etdTut &&
    sameDate(
      today,
      sevenDaysBefore(etdTut)
    )
  ) {


    categories.PREALERT.rows.push(

      createReminderRow(

        row,

        formatDate(
          sevenDaysBefore(etdTut)
        ),

        `PRE-ALERT DUE - ETD TUT - ${formatDate(etdTut)}`

      )

    );

  }


  // =====================================
  // 5. REVENUE
  // =====================================

  if (
    isEmpty(
      row["REVENUE"]
    )
  ) {


    categories.REVENUE.rows.push(

      createReminderRow(

        row,

        getRelevantShipmentDate(row),

        "JOB CLOSING PENDING"

      )

    );

  }

}


// ========================================
// RETURN ONLY CATEGORIES WITH ROWS
// ========================================

return Object
  .values(categories)

  .filter(
    category =>
      category.rows.length > 0
  )

  .map(
    category => ({

      json: category

    })
  );

const items = $input.all();

function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

const today = new Intl.DateTimeFormat("en-GB", {
  timeZone: "Asia/Kolkata",
  day: "2-digit",
  month: "2-digit",
  year: "numeric"
}).format(new Date());

const output = [];

for (const item of items) {

  const category = item.json.category;
  const title = item.json.title;
  const subject = item.json.subject;
  const rows = item.json.rows ?? [];

  // Skip empty categories
  if (rows.length === 0) {
    continue;
  }

  let tableRows = "";

  for (const row of rows) {

    tableRows += `
      <tr>
        <td style="border:1px solid #ccc;padding:8px;text-align:center;">
          ${escapeHtml(row.DATE)}
        </td>

        <td style="border:1px solid #ccc;padding:8px;">
          ${escapeHtml(row.SHIPPER)}
        </td>

        <td style="border:1px solid #ccc;padding:8px;">
          ${escapeHtml(row.CARRIER)}
        </td>

        <td style="border:1px solid #ccc;padding:8px;text-align:center;">
          ${escapeHtml(row["B.NO"])}
        </td>

        <td style="border:1px solid #ccc;padding:8px;text-align:center;">
          ${escapeHtml(row["JOB NO"])}
        </td>

        <td style="border:1px solid #ccc;padding:8px;text-align:center;">
          ${escapeHtml(row["MBL NO"])}
        </td>

        <td style="border:1px solid #ccc;padding:8px;text-align:center;">
          ${escapeHtml(row["CTNR NO"])}
        </td>

        <td style="
          border:1px solid #ccc;
          padding:8px;
          color:#C00000;
          font-weight:bold;
        ">
          ${escapeHtml(row.REASON)}
        </td>
      </tr>
    `;
  }

  const html = `
    <!DOCTYPE html>

    <html>

    <body style="
      font-family:Arial,sans-serif;
      margin:20px;
    ">

      <h2 style="color:#1F4E78;">
        ${escapeHtml(title)}
      </h2>

      <div style="
        background:#FFF3CD;
        border:1px solid #FFEEBA;
        padding:12px;
        margin-bottom:20px;
      ">

        <strong>Date:</strong>
        ${escapeHtml(today)}

        <br><br>

        <strong>Total Reminders:</strong>
        ${rows.length}

      </div>

      <table style="
        border-collapse:collapse;
        width:100%;
        font-size:13px;
      ">

        <thead>

          <tr style="
            background:#1F4E78;
            color:white;
          ">

            <th style="border:1px solid #ccc;padding:8px;">
              DATE
            </th>

            <th style="border:1px solid #ccc;padding:8px;">
              SHIPPER
            </th>

            <th style="border:1px solid #ccc;padding:8px;">
              CARRIER
            </th>

            <th style="border:1px solid #ccc;padding:8px;">
              B.NO
            </th>

            <th style="border:1px solid #ccc;padding:8px;">
              JOB NO
            </th>

            <th style="border:1px solid #ccc;padding:8px;">
              MBL NO
            </th>

            <th style="border:1px solid #ccc;padding:8px;">
              CTNR NO
            </th>

            <th style="border:1px solid #ccc;padding:8px;">
              REASON
            </th>

          </tr>

        </thead>

        <tbody>

          ${tableRows}

        </tbody>

      </table>

      <br><br>

      Regards,

      <br>

      <strong>Shipment Automation System</strong>

    </body>

    </html>
  `;

  output.push({
    json: {
      category: category,
      subject: `${subject} - ${today}`,
      html: html
    }
  });
}

return output;

const items = $input.all();

const data = $getWorkflowStaticData("global");

const today = new Intl.DateTimeFormat("en-CA", {
  timeZone: "Asia/Kolkata",
  year: "numeric",
  month: "2-digit",
  day: "2-digit"
}).format(new Date());

const output = [];

for (const item of items) {

  const category = item.json.category;

  if (!category) {
    continue;
  }

  const key = `lastSent_${category}`;

  if (data[key] === today) {
    continue;
  }

  output.push(item);
}

return output;

const items = $input.all();

const data = $getWorkflowStaticData("global");

const today = new Intl.DateTimeFormat("en-CA", {
  timeZone: "Asia/Kolkata",
  year: "numeric",
  month: "2-digit",
  day: "2-digit"
}).format(new Date());

for (const item of items) {

  const category = item.json.category;

  if (!category) {
    continue;
  }

  const key = `lastSent_${category}`;

  data[key] = today;
}

return items;
